@Test
public void testFlattenInMemoryEvaluator() throws Exception {
    TestPipeline p = TestPipeline.create();
    PCollection<Integer> left = p.apply("left", Create.of(1, 2, 4));
    PCollection<Integer> right = p.apply("right", Create.of(-1, 2, -4));
    PCollectionList<Integer> list = PCollectionList.of(left).and(right);
    PCollection<Integer> flattened = list.apply(Flatten.<Integer>pCollections());
    CommittedBundle<Integer> leftBundle = bundleFactory.createRootBundle(left).commit(Instant.now());
    CommittedBundle<Integer> rightBundle = bundleFactory.createRootBundle(right).commit(Instant.now());
    InProcessEvaluationContext context = mock(InProcessEvaluationContext.class);
    UncommittedBundle<Integer> flattenedLeftBundle = bundleFactory.createRootBundle(flattened);
    UncommittedBundle<Integer> flattenedRightBundle = bundleFactory.createRootBundle(flattened);
    when(context.createBundle(leftBundle, flattened)).thenReturn(flattenedLeftBundle);
    when(context.createBundle(rightBundle, flattened)).thenReturn(flattenedRightBundle);
    FlattenEvaluatorFactory factory = new FlattenEvaluatorFactory();
    TransformEvaluator<Integer> leftSideEvaluator = factory.forApplication(flattened.getProducingTransformInternal(), leftBundle, context);
    TransformEvaluator<Integer> rightSideEvaluator = factory.forApplication(flattened.getProducingTransformInternal(), rightBundle, context);
    leftSideEvaluator.processElement(WindowedValue.valueInGlobalWindow(1));
    rightSideEvaluator.processElement(WindowedValue.valueInGlobalWindow(-1));
    leftSideEvaluator.processElement(WindowedValue.timestampedValueInGlobalWindow(2, new Instant(1024)));
    leftSideEvaluator.processElement(WindowedValue.valueInEmptyWindows(4, PaneInfo.NO_FIRING));
    rightSideEvaluator.processElement(WindowedValue.valueInEmptyWindows(2, PaneInfo.ON_TIME_AND_ONLY_FIRING));
    rightSideEvaluator.processElement(WindowedValue.timestampedValueInGlobalWindow(-4, new Instant(-4096)));
    InProcessTransformResult rightSideResult = rightSideEvaluator.finishBundle();
    InProcessTransformResult leftSideResult = leftSideEvaluator.finishBundle();
    assertThat(rightSideResult.getOutputBundles(), Matchers.<UncommittedBundle<?>>contains(flattenedRightBundle));
    assertThat(rightSideResult.getTransform(), Matchers.<AppliedPTransform<?, ?, ?>>equalTo(flattened.getProducingTransformInternal()));
    assertThat(leftSideResult.getOutputBundles(), Matchers.<UncommittedBundle<?>>contains(flattenedLeftBundle));
    assertThat(leftSideResult.getTransform(), Matchers.<AppliedPTransform<?, ?, ?>>equalTo(flattened.getProducingTransformInternal()));
    assertThat(flattenedLeftBundle.commit(Instant.now()).getElements(), containsInAnyOrder(WindowedValue.timestampedValueInGlobalWindow(2, new Instant(1024)), WindowedValue.valueInEmptyWindows(4, PaneInfo.NO_FIRING), WindowedValue.valueInGlobalWindow(1)));
    assertThat(flattenedRightBundle.commit(Instant.now()).getElements(), containsInAnyOrder(WindowedValue.valueInEmptyWindows(2, PaneInfo.ON_TIME_AND_ONLY_FIRING), WindowedValue.timestampedValueInGlobalWindow(-4, new Instant(-4096)), WindowedValue.valueInGlobalWindow(-1)));
}

