@Test
public void testInMemoryEvaluator() throws Exception {
    TestPipeline p = TestPipeline.create();
    KV<String, Integer> firstFoo = KV.of("foo", -1);
    KV<String, Integer> secondFoo = KV.of("foo", 1);
    KV<String, Integer> thirdFoo = KV.of("foo", 3);
    KV<String, Integer> firstBar = KV.of("bar", 22);
    KV<String, Integer> secondBar = KV.of("bar", 12);
    KV<String, Integer> firstBaz = KV.of("baz", Integer.MAX_VALUE);
    PCollection<KV<String, Integer>> values = p.apply(Create.of(firstFoo, firstBar, secondFoo, firstBaz, secondBar, thirdFoo));
    PCollection<KV<String, WindowedValue<Integer>>> kvs = values.apply(new ReifyTimestampsAndWindows<String, Integer>());
    PCollection<KeyedWorkItem<String, Integer>> groupedKvs = kvs.apply(new InProcessGroupByKey.InProcessGroupByKeyOnly<String, Integer>());
    CommittedBundle<KV<String, WindowedValue<Integer>>> inputBundle = bundleFactory.createRootBundle(kvs).commit(Instant.now());
    InProcessEvaluationContext evaluationContext = mock(InProcessEvaluationContext.class);
    StructuralKey<String> fooKey = StructuralKey.of("foo", StringUtf8Coder.of());
    UncommittedBundle<KeyedWorkItem<String, Integer>> fooBundle = bundleFactory.createKeyedBundle(null, fooKey, groupedKvs);
    StructuralKey<String> barKey = StructuralKey.of("bar", StringUtf8Coder.of());
    UncommittedBundle<KeyedWorkItem<String, Integer>> barBundle = bundleFactory.createKeyedBundle(null, barKey, groupedKvs);
    StructuralKey<String> bazKey = StructuralKey.of("baz", StringUtf8Coder.of());
    UncommittedBundle<KeyedWorkItem<String, Integer>> bazBundle = bundleFactory.createKeyedBundle(null, bazKey, groupedKvs);
    when(evaluationContext.createKeyedBundle(inputBundle, fooKey, groupedKvs)).thenReturn(fooBundle);
    when(evaluationContext.createKeyedBundle(inputBundle, barKey, groupedKvs)).thenReturn(barBundle);
    when(evaluationContext.createKeyedBundle(inputBundle, bazKey, groupedKvs)).thenReturn(bazBundle);
    // The input to a GroupByKey is assumed to be a KvCoder
    @SuppressWarnings("unchecked")
    Coder<String> keyCoder = ((KvCoder<String, WindowedValue<Integer>>) kvs.getCoder()).getKeyCoder();
    TransformEvaluator<KV<String, WindowedValue<Integer>>> evaluator = new InProcessGroupByKeyOnlyEvaluatorFactory().forApplication(groupedKvs.getProducingTransformInternal(), inputBundle, evaluationContext);
    evaluator.processElement(WindowedValue.valueInEmptyWindows(gwValue(firstFoo)));
    evaluator.processElement(WindowedValue.valueInEmptyWindows(gwValue(secondFoo)));
    evaluator.processElement(WindowedValue.valueInEmptyWindows(gwValue(thirdFoo)));
    evaluator.processElement(WindowedValue.valueInEmptyWindows(gwValue(firstBar)));
    evaluator.processElement(WindowedValue.valueInEmptyWindows(gwValue(secondBar)));
    evaluator.processElement(WindowedValue.valueInEmptyWindows(gwValue(firstBaz)));
    evaluator.finishBundle();
    assertThat(fooBundle.commit(Instant.now()).getElements(), contains(new KeyedWorkItemMatcher<String, Integer>(KeyedWorkItems.elementsWorkItem("foo", ImmutableSet.of(WindowedValue.valueInGlobalWindow(-1), WindowedValue.valueInGlobalWindow(1), WindowedValue.valueInGlobalWindow(3))), keyCoder)));
    assertThat(barBundle.commit(Instant.now()).getElements(), contains(new KeyedWorkItemMatcher<String, Integer>(KeyedWorkItems.elementsWorkItem("bar", ImmutableSet.of(WindowedValue.valueInGlobalWindow(12), WindowedValue.valueInGlobalWindow(22))), keyCoder)));
    assertThat(bazBundle.commit(Instant.now()).getElements(), contains(new KeyedWorkItemMatcher<String, Integer>(KeyedWorkItems.elementsWorkItem("baz", ImmutableSet.of(WindowedValue.valueInGlobalWindow(Integer.MAX_VALUE))), keyCoder)));
}

