    assertThat(firstTransformFiredTimers.get(filtered.getProducingTransformInternal()), not(nullValue()));
    Map<StructuralKey<?>, FiredTimers> firstFilteredTimers = firstTransformFiredTimers.get(filtered.getProducingTransformInternal());
    assertThat(firstFilteredTimers.get(key), not(nullValue()));
    FiredTimers firstFired = firstFilteredTimers.get(key);
    assertThat(firstFired.getTimers(TimeDomain.EVENT_TIME), contains(earliestTimer));
    manager.updateWatermarks(null, TimerUpdate.empty(), result(createdInts.getProducingTransformInternal(), null, Collections.<CommittedBundle<?>>emptyList()), new Instant(50_000L));
    manager.refreshAll();
    Map<AppliedPTransform<?, ?, ?>, Map<StructuralKey<?>, FiredTimers>> secondTransformFiredTimers = manager.extractFiredTimers();
    assertThat(secondTransformFiredTimers.get(filtered.getProducingTransformInternal()), not(nullValue()));
    Map<StructuralKey<?>, FiredTimers> secondFilteredTimers = secondTransformFiredTimers.get(filtered.getProducingTransformInternal());
    assertThat(secondFilteredTimers.get(key), not(nullValue()));
