@Test
public void extractFiredTimersExtractsTimers() {
    InProcessTransformResult holdResult = StepTransformResult.withHold(created.getProducingTransformInternal(), new Instant(0)).build();
    context.handleResult(null, ImmutableList.<TimerData>of(), holdResult);
    StructuralKey<?> key = StructuralKey.of("foo".length(), VarIntCoder.of());
    TimerData toFire = TimerData.of(StateNamespaces.global(), new Instant(100L), TimeDomain.EVENT_TIME);
    InProcessTransformResult timerResult = StepTransformResult.withoutHold(downstream.getProducingTransformInternal()).withState(CopyOnAccessInMemoryStateInternals.withUnderlying(key, null)).withTimerUpdate(TimerUpdate.builder(key).setTimer(toFire).build()).build();
    // haven't added any timers, must be empty
    assertThat(context.extractFiredTimers().entrySet(), emptyIterable());
    context.handleResult(context.createKeyedBundle(null, key, created).commit(Instant.now()), ImmutableList.<TimerData>of(), timerResult);
    // timer hasn't fired
    assertThat(context.extractFiredTimers().entrySet(), emptyIterable());
    InProcessTransformResult advanceResult = StepTransformResult.withoutHold(created.getProducingTransformInternal()).build();
    // Should cause the downstream timer to fire
    context.handleResult(null, ImmutableList.<TimerData>of(), advanceResult);
    Map<AppliedPTransform<?, ?, ?>, Map<StructuralKey<?>, FiredTimers>> fired = context.extractFiredTimers();
    assertThat(fired, Matchers.<AppliedPTransform<?, ?, ?>>hasKey(downstream.getProducingTransformInternal()));
    Map<StructuralKey<?>, FiredTimers> downstreamFired = fired.get(downstream.getProducingTransformInternal());
    assertThat(downstreamFired, Matchers.<Object>hasKey(key));
    FiredTimers firedForKey = downstreamFired.get(key);
    assertThat(firedForKey.getTimers(TimeDomain.PROCESSING_TIME), emptyIterable());
    assertThat(firedForKey.getTimers(TimeDomain.SYNCHRONIZED_PROCESSING_TIME), emptyIterable());
    assertThat(firedForKey.getTimers(TimeDomain.EVENT_TIME), contains(toFire));
    // Don't reextract timers
    assertThat(context.extractFiredTimers().entrySet(), emptyIterable());
}

