        @Override
        public void processElement(ProcessContext c) {
            c.output(KV.<String, Integer>of(c.element(), c.element().length()));
            c.sideOutput(elementTag, c.element());
            c.sideOutput(lengthTag, c.element().length());
        }
    }).withOutputTags(mainOutputTag, TupleTagList.of(elementTag).and(lengthTag));
    PCollectionTuple outputTuple = input.apply(pardo);
    CommittedBundle<String> inputBundle = bundleFactory.createRootBundle(input).commit(Instant.now());
    PCollection<KV<String, Integer>> mainOutput = outputTuple.get(mainOutputTag);
    PCollection<String> elementOutput = outputTuple.get(elementTag);
    PCollection<Integer> lengthOutput = outputTuple.get(lengthTag);
    InProcessEvaluationContext evaluationContext = mock(InProcessEvaluationContext.class);
    UncommittedBundle<KV<String, Integer>> mainOutputBundle = bundleFactory.createRootBundle(mainOutput);
    UncommittedBundle<String> elementOutputBundle = bundleFactory.createRootBundle(elementOutput);
    UncommittedBundle<Integer> lengthOutputBundle = bundleFactory.createRootBundle(lengthOutput);
    when(evaluationContext.createBundle(inputBundle, mainOutput)).thenReturn(mainOutputBundle);
    when(evaluationContext.createBundle(inputBundle, elementOutput)).thenReturn(elementOutputBundle);
    when(evaluationContext.createBundle(inputBundle, lengthOutput)).thenReturn(lengthOutputBundle);
    InProcessExecutionContext executionContext = new InProcessExecutionContext(null, null, null, null);
    when(evaluationContext.getExecutionContext(mainOutput.getProducingTransformInternal(), inputBundle.getKey())).thenReturn(executionContext);
    CounterSet counters = new CounterSet();
    when(evaluationContext.createCounterSet()).thenReturn(counters);
    TransformEvaluator<String> evaluator = new ParDoMultiEvaluatorFactory().forApplication(mainOutput.getProducingTransformInternal(), inputBundle, evaluationContext);
    evaluator.processElement(WindowedValue.valueInGlobalWindow("foo"));
    evaluator.processElement(WindowedValue.timestampedValueInGlobalWindow("bara", new Instant(1000)));
    evaluator.processElement(WindowedValue.valueInGlobalWindow("bazam", PaneInfo.ON_TIME_AND_ONLY_FIRING));
    InProcessTransformResult result = evaluator.finishBundle();
    assertThat(result.getOutputBundles(), Matchers.<UncommittedBundle<?>>containsInAnyOrder(lengthOutputBundle, mainOutputBundle, elementOutputBundle));
    assertThat(result.getWatermarkHold(), equalTo(BoundedWindow.TIMESTAMP_MAX_VALUE));
    assertThat(result.getCounters(), equalTo(counters));
    assertThat(mainOutputBundle.commit(Instant.now()).getElements(), Matchers.<WindowedValue<KV<String, Integer>>>containsInAnyOrder(WindowedValue.valueInGlobalWindow(KV.of("foo", 3)), WindowedValue.timestampedValueInGlobalWindow(KV.of("bara", 4), new Instant(1000)), WindowedValue.valueInGlobalWindow(KV.of("bazam", 5), PaneInfo.ON_TIME_AND_ONLY_FIRING)));
    assertThat(elementOutputBundle.commit(Instant.now()).getElements(), Matchers.<WindowedValue<String>>containsInAnyOrder(WindowedValue.valueInGlobalWindow("foo"), WindowedValue.timestampedValueInGlobalWindow("bara", new Instant(1000)), WindowedValue.valueInGlobalWindow("bazam", PaneInfo.ON_TIME_AND_ONLY_FIRING)));
    assertThat(lengthOutputBundle.commit(Instant.now()).getElements(), Matchers.<WindowedValue<Integer>>containsInAnyOrder(WindowedValue.valueInGlobalWindow(3), WindowedValue.timestampedValueInGlobalWindow(4, new Instant(1000)), WindowedValue.valueInGlobalWindow(5, PaneInfo.ON_TIME_AND_ONLY_FIRING)));
