        @Override
        public void processElement(ProcessContext c) {
            c.windowingInternals().stateInternals().state(StateNamespaces.global(), watermarkTag).add(new Instant(124443L - c.element().length()));
            c.windowingInternals().stateInternals().state(StateNamespaces.window(GlobalWindow.Coder.INSTANCE, GlobalWindow.INSTANCE), bagTag).add(c.element());
        }
    });
    PCollection<KV<String, Integer>> mainOutput = input.apply(pardo);
