    PCollection<byte[]> pcBytes = created.apply(new PTransform<PCollection<String>, PCollection<byte[]>>() {

        @Override
        public PCollection<byte[]> apply(PCollection<String> input) {
            return PCollection.<byte[]>createPrimitiveOutputInternal(input.getPipeline(), input.getWindowingStrategy(), input.isBounded()).setCoder(ByteArrayCoder.of());
        }
    });
    final InProcessTransformResult result = StepTransformResult.withoutHold(pcBytes.getProducingTransformInternal()).build();
    final CountDownLatch testLatch = new CountDownLatch(1);
    final CountDownLatch evaluatorLatch = new CountDownLatch(1);
    TransformEvaluator<Object> evaluator = new TransformEvaluator<Object>() {

        @Override
        public void processElement(WindowedValue<Object> element) throws Exception {
        }

        @Override
        public InProcessTransformResult finishBundle() throws Exception {
            testLatch.countDown();
            evaluatorLatch.await();
            return result;
        }
    };
    WindowedValue<byte[]> fooBytes = WindowedValue.valueInGlobalWindow("foo".getBytes());
    CommittedBundle<byte[]> inputBundle = bundleFactory.createRootBundle(pcBytes).add(fooBytes).commit(Instant.now());
    when(registry.forApplication(pcBytes.getProducingTransformInternal(), inputBundle, evaluationContext)).thenReturn(evaluator);
    TransformExecutor<byte[]> executor = TransformExecutor.create(registry, Collections.<ModelEnforcementFactory>singleton(ImmutabilityEnforcementFactory.create()), evaluationContext, inputBundle, pcBytes.getProducingTransformInternal(), completionCallback, transformEvaluationState);
    Future<?> task = Executors.newSingleThreadExecutor().submit(executor);
    testLatch.await();
    fooBytes.getValue()[0] = 'b';
    evaluatorLatch.countDown();
    thrown.expectCause(isA(IllegalMutationException.class));
    task.get();
}

