@Test
public void singleWindowFnSucceeds() throws Exception {
    Duration windowDuration = Duration.standardDays(7);
    Bound<Long> transform = Window.<Long>into(FixedWindows.of(windowDuration));
    PCollection<Long> windowed = input.apply(transform);
    CommittedBundle<Long> inputBundle = createInputBundle();
    UncommittedBundle<Long> outputBundle = createOutputBundle(windowed, inputBundle);
    BoundedWindow firstSecondWindow = new IntervalWindow(EPOCH, EPOCH.plus(windowDuration));
    BoundedWindow thirdWindow = new IntervalWindow(EPOCH.minus(windowDuration), EPOCH);
    InProcessTransformResult result = runEvaluator(windowed, inputBundle, transform);
    assertThat(Iterables.getOnlyElement(result.getOutputBundles()), Matchers.<UncommittedBundle<?>>equalTo(outputBundle));
    CommittedBundle<Long> committed = outputBundle.commit(Instant.now());
    WindowedValue<Long> expectedNewFirst = WindowedValue.of(3L, new Instant(2L), firstSecondWindow, PaneInfo.NO_FIRING);
    WindowedValue<Long> expectedNewSecond = WindowedValue.of(1L, EPOCH.plus(Duration.standardDays(3)), firstSecondWindow, PaneInfo.NO_FIRING);
    WindowedValue<Long> expectedNewThird = WindowedValue.of(2L, new Instant(-10L), thirdWindow, PaneInfo.NO_FIRING);
    assertThat(committed.getElements(), containsInAnyOrder(expectedNewFirst, expectedNewSecond, expectedNewThird));
}

@Test
public void multipleWindowsWindowFnSucceeds() throws Exception {
    Duration windowDuration = Duration.standardDays(6);
    Duration slidingBy = Duration.standardDays(3);
    Bound<Long> transform = Window.into(SlidingWindows.of(windowDuration).every(slidingBy));
    PCollection<Long> windowed = input.apply(transform);
    CommittedBundle<Long> inputBundle = createInputBundle();
    UncommittedBundle<Long> outputBundle = createOutputBundle(windowed, inputBundle);
    InProcessTransformResult result = runEvaluator(windowed, inputBundle, transform);
    assertThat(Iterables.getOnlyElement(result.getOutputBundles()), Matchers.<UncommittedBundle<?>>equalTo(outputBundle));
    CommittedBundle<Long> committed = outputBundle.commit(Instant.now());
    BoundedWindow w1 = new IntervalWindow(EPOCH, EPOCH.plus(windowDuration));
    BoundedWindow w2 = new IntervalWindow(EPOCH.plus(slidingBy), EPOCH.plus(slidingBy).plus(windowDuration));
    BoundedWindow wMinus1 = new IntervalWindow(EPOCH.minus(windowDuration), EPOCH);
    BoundedWindow wMinusSlide = new IntervalWindow(EPOCH.minus(windowDuration).plus(slidingBy), EPOCH.plus(slidingBy));
    WindowedValue<Long> expectedFirst = WindowedValue.of(first.getValue(), first.getTimestamp(), ImmutableSet.of(w1, wMinusSlide), PaneInfo.NO_FIRING);
    WindowedValue<Long> expectedSecond = WindowedValue.of(second.getValue(), second.getTimestamp(), ImmutableSet.of(w1, w2), PaneInfo.NO_FIRING);
    WindowedValue<Long> expectedThird = WindowedValue.of(third.getValue(), third.getTimestamp(), ImmutableSet.of(wMinus1, wMinusSlide), PaneInfo.NO_FIRING);
    assertThat(committed.getElements(), containsInAnyOrder(expectedFirst, expectedSecond, expectedThird));
}

