@Test
public void testWithLateness() throws Exception {
    WindowingStrategy strategy = WindowingStrategy.of(FixedWindows.of(Duration.standardSeconds(2))).withMode(WindowingStrategy.AccumulationMode.ACCUMULATING_FIRED_PANES).withOutputTimeFn(OutputTimeFns.outputAtEarliestInputTimestamp()).withAllowedLateness(Duration.millis(1000));
    long initialTime = 0L;
    Pipeline pipeline = FlinkTestPipeline.createForStreaming();
    KvCoder<String, Integer> inputCoder = KvCoder.of(StringUtf8Coder.of(), VarIntCoder.of());
    FlinkGroupAlsoByWindowWrapper gbwOperaror = FlinkGroupAlsoByWindowWrapper.createForTesting(pipeline.getOptions(), pipeline.getCoderRegistry(), strategy, inputCoder, combiner.<String>asKeyedFn());
    OneInputStreamOperatorTestHarness<WindowedValue<KV<String, Integer>>, WindowedValue<KV<String, Integer>>> testHarness = new OneInputStreamOperatorTestHarness<>(gbwOperaror);
    testHarness.open();
    testHarness.processElement(new StreamRecord<>(makeWindowedValue(strategy, KV.of("key1", 1), new Instant(initialTime + 1), null, PaneInfo.NO_FIRING), initialTime + 20));
    testHarness.processElement(new StreamRecord<>(makeWindowedValue(strategy, KV.of("key1", 1), new Instant(initialTime + 1), null, PaneInfo.NO_FIRING), initialTime + 20));
    testHarness.processElement(new StreamRecord<>(makeWindowedValue(strategy, KV.of("key1", 1), new Instant(initialTime + 1000), null, PaneInfo.NO_FIRING), initialTime + 20));
    testHarness.processElement(new StreamRecord<>(makeWindowedValue(strategy, KV.of("key1", 1), new Instant(initialTime + 1200), null, PaneInfo.NO_FIRING), initialTime + 20));
    testHarness.processWatermark(new Watermark(initialTime + 2000));
    testHarness.processElement(new StreamRecord<>(makeWindowedValue(strategy, KV.of("key1", 1), new Instant(initialTime + 1200), null, PaneInfo.NO_FIRING), initialTime + 20));
    testHarness.processElement(new StreamRecord<>(makeWindowedValue(strategy, KV.of("key1", 1), new Instant(initialTime + 1200), null, PaneInfo.NO_FIRING), initialTime + 20));
    testHarness.processWatermark(new Watermark(initialTime + 4000));
    ConcurrentLinkedQueue<Object> expectedOutput = new ConcurrentLinkedQueue<>();
    expectedOutput.add(new StreamRecord<>(WindowedValue.of(KV.of("key1", 4), new Instant(initialTime + 1), new IntervalWindow(new Instant(0), new Instant(2000)), PaneInfo.createPane(true, false, PaneInfo.Timing.ON_TIME, 0, 0)), initialTime + 1));
    expectedOutput.add(new Watermark(initialTime + 2000));
    expectedOutput.add(new StreamRecord<>(WindowedValue.of(KV.of("key1", 5), new Instant(initialTime + 1999), new IntervalWindow(new Instant(0), new Instant(2000)), PaneInfo.createPane(false, false, PaneInfo.Timing.LATE, 1, 1)), initialTime + 1999));
    expectedOutput.add(new StreamRecord<>(WindowedValue.of(KV.of("key1", 6), new Instant(initialTime + 1999), new IntervalWindow(new Instant(0), new Instant(2000)), PaneInfo.createPane(false, false, PaneInfo.Timing.LATE, 2, 2)), initialTime + 1999));
    expectedOutput.add(new Watermark(initialTime + 4000));
    TestHarnessUtil.assertOutputEqualsSorted("Output was not correct.", expectedOutput, testHarness.getOutput(), new ResultSortComparator());
    testHarness.close();
}

