    WindowingStrategy strategy = slidingWindowWithAfterWatermarkTriggerStrategy;
    long initialTime = 0L;
    OneInputStreamOperatorTestHarness<WindowedValue<KV<String, Integer>>, WindowedValue<KV<String, Integer>>> testHarness = createTestingOperatorAndState(strategy, initialTime);
