    expectedOutput.add(new StreamRecord<>(WindowedValue.of(KV.of("key1", 11), new Instant(initialTime + 15000), new IntervalWindow(new Instant(10000), new Instant(20000)), PaneInfo.createPane(true, true, PaneInfo.Timing.ON_TIME)), initialTime + 15000));
