/**
 * Creates a {@link UnboundedSourceWrapper} that has exactly one reader per source, since we
 * specify a parallelism of 1 and also at runtime tell the source that it has 1 parallel subtask.
 */
@Test
public void testWithOneReader() throws Exception {
    final int NUM_ELEMENTS = 20;
    final Object checkpointLock = new Object();
    PipelineOptions options = PipelineOptionsFactory.create();
    // this source will emit exactly NUM_ELEMENTS across all parallel readers,
    // afterwards it will stall. We check whether we also receive NUM_ELEMENTS
    // elements later.
    TestCountingSource source = new TestCountingSource(NUM_ELEMENTS);
    UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark> flinkWrapper = new UnboundedSourceWrapper<>(options, source, 1);
    assertEquals(1, flinkWrapper.getSplitSources().size());
    StreamSource<WindowedValue<KV<Integer, Integer>>, UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark>> sourceOperator = new StreamSource<>(flinkWrapper);
    setupSourceOperator(sourceOperator);
    try {
        sourceOperator.run(checkpointLock, new Output<StreamRecord<WindowedValue<KV<Integer, Integer>>>>() {

            private int count = 0;

            @Override
            public void emitWatermark(Watermark watermark) {
            }

            @Override
            public void collect(StreamRecord<WindowedValue<KV<Integer, Integer>>> windowedValueStreamRecord) {
                count++;
                if (count >= NUM_ELEMENTS) {
                    throw new SuccessException();
                }
            }

            @Override
            public void close() {
            }
        });
    } catch (SuccessException e) {
        // success
    } catch (Exception e) {
        fail("We caught " + e);
    }
}

