@Test
public void testTransformTranslator() throws IOException {
    // Test that we can provide a custom translation
    DataflowPipelineOptions options = buildPipelineOptions();
    Pipeline p = Pipeline.create(options);
    TestTransform transform = new TestTransform();
    p.apply(Create.of(Arrays.asList(1, 2, 3)).withCoder(BigEndianIntegerCoder.of())).apply(transform);
    DataflowPipelineTranslator translator = DataflowPipelineRunner.fromOptions(options).getTranslator();
    DataflowPipelineTranslator.registerTransformTranslator(TestTransform.class, new DataflowPipelineTranslator.TransformTranslator<TestTransform>() {

        @SuppressWarnings("unchecked")
        @Override
        public void translate(TestTransform transform, DataflowPipelineTranslator.TranslationContext context) {
            transform.translated = true;
            // Note: This is about the minimum needed to fake out a
            // translation. This obviously isn't a real translation.
            context.addStep(transform, "TestTranslate");
            context.addOutput("output", context.getOutput(transform));
        }
    });
    translator.translate(p, (DataflowPipelineRunner) p.getRunner(), Collections.<DataflowPackage>emptyList());
    assertTrue(transform.translated);
}

@Test
public void testApplyIsScopedToExactClass() throws IOException {
    DataflowPipelineOptions options = buildPipelineOptions();
    Pipeline p = Pipeline.create(options);
    Create.TimestampedValues<String> transform = Create.timestamped(Arrays.asList(TimestampedValue.of("TestString", Instant.now())));
    p.apply(transform);
    CompositeTransformRecorder recorder = new CompositeTransformRecorder();
    p.traverseTopologically(recorder);
    // The recorder will also have seen a Create.Values composite as well, but we can't obtain that
    // transform.
    assertThat("Expected to have seen CreateTimestamped composite transform.", recorder.getCompositeTransforms(), hasItem(transform));
    assertThat("Expected to have two composites, CreateTimestamped and Create.Values", recorder.getCompositeTransforms(), hasItem(Matchers.<PTransform<?, ?>>isA((Class) Create.Values.class)));
}

