    byte[] allOnes = new byte[] { 1, 1, 1, 1 };
    byte[] findIn = new byte[] { 1, 1, 1, 1 };
    Seeker s = new Seeker(marker);
    for (int i = 0; i < findIn.length; i++) {
        assertEquals(-1, s.find(allOnes, allOnes.length));
        findIn[i] = 2;
        assertEquals(i, s.find(findIn, findIn.length));
        findIn[i] = 1;
    }
}

