@Test
@Category(RunnableOnService.class)
public void testComposedCombine() {
    Pipeline p = TestPipeline.create();
    p.getCoderRegistry().registerCoder(UserString.class, UserStringCoder.of());
    PCollection<KV<String, KV<Integer, UserString>>> perKeyInput = p.apply(Create.timestamped(Arrays.asList(KV.of("a", KV.of(1, UserString.of("1"))), KV.of("a", KV.of(1, UserString.of("1"))), KV.of("a", KV.of(4, UserString.of("4"))), KV.of("b", KV.of(1, UserString.of("1"))), KV.of("b", KV.of(13, UserString.of("13")))), Arrays.asList(0L, 4L, 7L, 10L, 16L)).withCoder(KvCoder.of(StringUtf8Coder.of(), KvCoder.of(BigEndianIntegerCoder.of(), UserStringCoder.of()))));
    TupleTag<Integer> maxIntTag = new TupleTag<Integer>();
    TupleTag<UserString> concatStringTag = new TupleTag<UserString>();
    PCollection<KV<String, KV<Integer, String>>> combineGlobally = perKeyInput.apply(Values.<KV<Integer, UserString>>create()).apply(Combine.globally(CombineFns.compose().with(new GetIntegerFunction(), new MaxIntegerFn(), maxIntTag).with(new GetUserStringFunction(), new ConcatString(), concatStringTag))).apply(WithKeys.<String, CoCombineResult>of("global")).apply("ExtractGloballyResult", ParDo.of(new ExtractResultDoFn(maxIntTag, concatStringTag)));
    PCollection<KV<String, KV<Integer, String>>> combinePerKey = perKeyInput.apply(Combine.perKey(CombineFns.composeKeyed().with(new GetIntegerFunction(), new MaxIntegerFn().<String>asKeyedFn(), maxIntTag).with(new GetUserStringFunction(), new ConcatString().<String>asKeyedFn(), concatStringTag))).apply("ExtractPerKeyResult", ParDo.of(new ExtractResultDoFn(maxIntTag, concatStringTag)));
    PAssert.that(combineGlobally).containsInAnyOrder(KV.of("global", KV.of(13, "111134")));
    PAssert.that(combinePerKey).containsInAnyOrder(KV.of("a", KV.of(4, "114")), KV.of("b", KV.of(13, "113")));
    p.run();
}

