/**
 * Tests that the consuming DoFn
 * (CorrelatePurchaseCountForAddressesWithoutNamesFn) performs as expected.
 */
@SuppressWarnings("unchecked")
@Test
public void testConsumingDoFn() {
    TupleTag<String> purchasesTag = new TupleTag<>();
    TupleTag<String> addressesTag = new TupleTag<>();
    TupleTag<String> namesTag = new TupleTag<>();
    // result1 should get filtered out because it has a name.
    CoGbkResult result1 = CoGbkResult.of(purchasesTag, Arrays.asList("3a", "3b")).and(addressesTag, Arrays.asList("2a", "2b")).and(namesTag, Arrays.asList("1a"));
    // result 2 should be counted because it has an address and purchases.
    CoGbkResult result2 = CoGbkResult.of(purchasesTag, Arrays.asList("5a", "5b")).and(addressesTag, Arrays.asList("4a")).and(namesTag, new ArrayList<String>());
    // result 3 should not be counted because it has no addresses.
    CoGbkResult result3 = CoGbkResult.of(purchasesTag, Arrays.asList("7a", "7b")).and(addressesTag, new ArrayList<String>()).and(namesTag, new ArrayList<String>());
    // result 4 should be counted as 0, because it has no purchases.
    CoGbkResult result4 = CoGbkResult.of(purchasesTag, new ArrayList<String>()).and(addressesTag, Arrays.asList("8a")).and(namesTag, new ArrayList<String>());
    List<KV<String, Integer>> results = DoFnTester.of(new CorrelatePurchaseCountForAddressesWithoutNamesFn(purchasesTag, addressesTag, namesTag)).processBatch(KV.of(1, result1), KV.of(2, result2), KV.of(3, result3), KV.of(4, result4));
    assertThat(results, containsInAnyOrder(KV.of("4a", 2), KV.of("8a", 0)));
}

