@Test
public void testCompatibility() {
    // Equal counters are compatible, of all kinds.
    assertTrue(Counter.longs("c", SUM).isCompatibleWith(Counter.longs("c", SUM)));
    assertTrue(Counter.ints("c", SUM).isCompatibleWith(Counter.ints("c", SUM)));
    assertTrue(Counter.doubles("c", SUM).isCompatibleWith(Counter.doubles("c", SUM)));
    assertTrue(Counter.booleans("c", OR).isCompatibleWith(Counter.booleans("c", OR)));
    // The name, kind, and type of the counter must match.
    assertFalse(Counter.longs("c", SUM).isCompatibleWith(Counter.longs("c2", SUM)));
    assertFalse(Counter.longs("c", SUM).isCompatibleWith(Counter.longs("c", MAX)));
    assertFalse(Counter.longs("c", SUM).isCompatibleWith(Counter.ints("c", SUM)));
    // The value of the counters are ignored.
    assertTrue(Counter.longs("c", SUM).resetToValue(666L).isCompatibleWith(Counter.longs("c", SUM).resetToValue(42L)));
}

