@Test
public void movingSum() {
    MovingFunction f = newFunc();
    int lost = 0;
    for (int i = 0; i < SAMPLE_PERIOD * 2; i++) {
        f.add(i, 1);
        if (i >= SAMPLE_PERIOD) {
            if (i % SAMPLE_UPDATE == 0) {
                lost += SAMPLE_UPDATE;
            }
        }
        assertEquals(i + 1 - lost, f.get(i));
    }
}

@Test
public void jumpingSum() {
    MovingFunction f = newFunc();
    f.add(0, 1);
    f.add(SAMPLE_PERIOD - 1, 1);
    assertEquals(2, f.get(SAMPLE_PERIOD - 1));
    assertEquals(1, f.get(SAMPLE_PERIOD + 3 * SAMPLE_UPDATE));
    assertEquals(0, f.get(SAMPLE_PERIOD * 2));
}

/**
 * Tests that {@link MutationDetectors#forValueWithCoder} detects a mutation to a list.
 */
@Test
public void testMutatingList() throws Exception {
    List<Integer> value = Arrays.asList(1, 2, 3, 4);
    MutationDetector detector = MutationDetectors.forValueWithCoder(value, ListCoder.of(VarIntCoder.of()));
    value.set(0, 37);
    thrown.expect(IllegalMutationException.class);
    detector.verifyUnmodified();
}

/**
 * Tests that {@link MutationDetectors#forValueWithCoder} does not false positive on a
 * {@link LinkedList} that will clone as an {@code ArrayList}.
 */
@Test
public void testUnmodifiedLinkedList() throws Exception {
    List<Integer> value = Lists.newLinkedList(Arrays.asList(1, 2, 3, 4));
    MutationDetector detector = MutationDetectors.forValueWithCoder(value, ListCoder.of(VarIntCoder.of()));
    detector.verifyUnmodified();
}

/**
 * Tests that {@link MutationDetectors#forValueWithCoder} does not false positive on a
 * {@link LinkedList} coded as an {@link Iterable}.
 */
@Test
public void testImmutableList() throws Exception {
    List<Integer> value = Lists.newLinkedList(Arrays.asList(1, 2, 3, 4));
