@Test
public void testOnElementBufferingDiscarding() throws Exception {
    // Test basic execution of a trigger using a non-combining window set and discarding mode.
    ReduceFnTester<Integer, Iterable<Integer>, IntervalWindow> tester = ReduceFnTester.nonCombining(FixedWindows.of(Duration.millis(10)), mockTrigger, AccumulationMode.DISCARDING_FIRED_PANES, Duration.millis(100), ClosingBehavior.FIRE_IF_NON_EMPTY);
    // Pane of {1, 2}
    injectElement(tester, 1);
    when(mockTrigger.shouldFire(anyTriggerContext())).thenReturn(true);
    injectElement(tester, 2);
    assertThat(tester.extractOutput(), contains(isSingleWindowedValue(containsInAnyOrder(1, 2), 1, 0, 10)));
    // Pane of just 3, and finish
    when(mockTrigger.shouldFire(anyTriggerContext())).thenReturn(true);
    triggerShouldFinish(mockTrigger);
    injectElement(tester, 3);
    assertThat(tester.extractOutput(), contains(isSingleWindowedValue(containsInAnyOrder(3), 3, 0, 10)));
    assertTrue(tester.isMarkedFinished(firstWindow));
    tester.assertHasOnlyGlobalAndFinishedSetsFor(firstWindow);
    // This element shouldn't be seen, because the trigger has finished
    injectElement(tester, 4);
    assertEquals(1, tester.getElementsDroppedDueToClosedWindow());
}

@Test
public void testOnElementBufferingAccumulating() throws Exception {
    // Test basic execution of a trigger using a non-combining window set and accumulating mode.
    ReduceFnTester<Integer, Iterable<Integer>, IntervalWindow> tester = ReduceFnTester.nonCombining(FixedWindows.of(Duration.millis(10)), mockTrigger, AccumulationMode.ACCUMULATING_FIRED_PANES, Duration.millis(100), ClosingBehavior.FIRE_IF_NON_EMPTY);
    injectElement(tester, 1);
    // Fires {1, 2}
    when(mockTrigger.shouldFire(anyTriggerContext())).thenReturn(true);
    injectElement(tester, 2);
    // Fires {1, 2, 3} because we are in accumulating mode
    when(mockTrigger.shouldFire(anyTriggerContext())).thenReturn(true);
    triggerShouldFinish(mockTrigger);
    injectElement(tester, 3);
    // This element shouldn't be seen, because the trigger has finished
    injectElement(tester, 4);
    assertThat(tester.extractOutput(), contains(isSingleWindowedValue(containsInAnyOrder(1, 2), 1, 0, 10), isSingleWindowedValue(containsInAnyOrder(1, 2, 3), 3, 0, 10)));
    assertTrue(tester.isMarkedFinished(firstWindow));
    tester.assertHasOnlyGlobalAndFinishedSetsFor(firstWindow);
}

