@Test
public void testLevenshteinDistance() {
    // equal
    assertEquals(0, StringUtils.getLevenshteinDistance("", ""));
    // first empty
    assertEquals(3, StringUtils.getLevenshteinDistance("", "abc"));
    // second empty
    assertEquals(3, StringUtils.getLevenshteinDistance("abc", ""));
    // completely different
    assertEquals(5, StringUtils.getLevenshteinDistance("abc", "12345"));
    // deletion
    assertEquals(1, StringUtils.getLevenshteinDistance("abc", "ac"));
    // insertion
    assertEquals(1, StringUtils.getLevenshteinDistance("abc", "ab1c"));
    // modification
    assertEquals(1, StringUtils.getLevenshteinDistance("abc", "a1c"));
}

@Test
public void testGetStringParameter() throws Exception {
    Map<String, Object> o = makeCloudDictionary();
    Assert.assertEquals("stringValue", getString(o, "singletonStringKey"));
    Assert.assertEquals("stringValue", getString(o, "singletonStringKey", "defaultValue"));
    Assert.assertEquals("defaultValue", getString(o, "missingKey", "defaultValue"));
    try {
        getString(o, "missingKey");
        Assert.fail("should have thrown an exception");
    } catch (Exception exn) {
        Assert.assertThat(exn.toString(), Matchers.containsString("didn't find required parameter missingKey"));
    }
    try {
        getString(o, "noStringsKey");
        Assert.fail("should have thrown an exception");
    } catch (Exception exn) {
        Assert.assertThat(exn.toString(), Matchers.containsString("not a string"));
    }
    Assert.assertThat(getStrings(o, "noStringsKey", null), Matchers.<String>emptyIterable());
    Assert.assertThat(getObject(o, "noStringsKey").keySet(), Matchers.<String>emptyIterable());
    Assert.assertThat(getDictionary(o, "noStringsKey").keySet(), Matchers.<String>emptyIterable());
    Assert.assertThat(getDictionary(o, "noStringsKey", null).keySet(), Matchers.<String>emptyIterable());
    try {
        getString(o, "multipleStringsKey");
        Assert.fail("should have thrown an exception");
    } catch (Exception exn) {
        Assert.assertThat(exn.toString(), Matchers.containsString("not a string"));
    }
    try {
        getString(o, "emptyKey");
        Assert.fail("should have thrown an exception");
    } catch (Exception exn) {
        Assert.assertThat(exn.toString(), Matchers.containsString("not a string"));
    }
}

