    PAssert.that(timestampedVals).containsInAnyOrder(KV.of("0", new Instant(0)), KV.of("1234", new Instant("1234")), KV.of(Integer.toString(Integer.MAX_VALUE), new Instant(Integer.MAX_VALUE)), KV.of(yearTwoThousand, new Instant(Long.valueOf(yearTwoThousand))));
}
